query employee($where:EmployeeWhereInput!){
  employee(where:$where) {
    edges {
      node {
        id
        firstName
        lastName
        employeeClocks(first:1 where:{employeeClockStatus:{complete:{_eq:false}}} orderBy:{field:createdAt}) {
          edges {
            node {
              id
              startedAt
              completedAt
            }
          }
        } 
      }
    }
  }
  newStatus: employeeClockStatus(first:1 where:{complete:{_eq:false} approved:{_eq:false} exported:{_eq:false}}) {
    edges {
      node {
        id
      }
    }
  }
  completedStatus: employeeClockStatus(first:1 where:{complete:{_eq:true} approved:{_eq:false} exported:{_eq:false}}) {
    edges {
      node {
        id
      }
    }
  }
}

